// expect: exit 55
// screen: 0 25 16 9 4 1 = 55
struct node {
    int v;
    struct node *next;
};
int main(void)
{
    struct node *head = 0, *n;
    int i, sum = 0;
    cls();
    for (i = 1; i <= 5; i++) {
        n = malloc(sizeof(struct node));
        if (!n)
            return 1;
        n->v = i * i;
        n->next = head;
        head = n;
    }
    for (n = head; n; n = n->next) {
        printf("%d ", n->v);
        sum += n->v;
    }
    printf("= %d\n", sum);
    while (head) {
        n = head->next;
        free(head);
        head = n;
    }
    return sum;
}
